  if(v===0)return numeric(`A brick weighs ${W} N and measures ${a} cm × ${b} cm × ${c} cm. It can rest on any face. What is the greatest pressure it can exert on the floor, in N/cm²?`,round(W/areas[0],3),{unit:'N/cm²',units:P_UNITS,tol:0.01,method:'Greatest pressure comes from the smallest area: pressure = weight ÷ smallest face area.',steps:[`Smallest face = ${a} × ${b} = ${areas[0]} cm².`,`Pressure = ${W} ÷ ${areas[0]} = ${round(W/areas[0],3)} N/cm².`]});
