/* ---------------- Chemical change, acids and alkalis ---------------- */
const CHANGES=[['burning a sheet of paper',1,'Burning makes new substances, such as ash and carbon dioxide.'],['melting a bar of chocolate',0,'Melted chocolate is still chocolate; only its state changed.'],['dissolving sugar in water',0,'The sugar is still sugar, spread out through the water.'],['frying an egg',1,'Heating forms new substances, and the egg cannot change back.'],['an iron nail rusting',1,'Rust is a new substance made from iron, water and oxygen.'],['boiling water in a kettle',0,'The bubbles are steam, which is still the same water.'],['baking soda fizzing in vinegar',1,'A new gas, carbon dioxide, is made in the reaction.'],['cutting a plank of wood',0,'The pieces are still wood; only their size and shape changed.']];
